using System.ComponentModel;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Web;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

// --- Build the chat client with tool support ---
var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()   // automatically invoke tools when the model calls them
    .Build();

// --- Instantiate tools ---
var notebook = new Notebook();
var webSearch = new WebSearch();

var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(webSearch.SearchAsync),
        AIFunctionFactory.Create(notebook.AddNote),
        AIFunctionFactory.Create(notebook.GetNotes),
    ]
};

// --- System prompt ---
const string SystemPrompt = """
    You are a research agent. The user gives you a topic and you:
      1. Search the web several times to gather diverse information.
      2. Save the most important findings as notes using the note-taking tool.
      3. After you have enough information, retrieve your notes and produce a
         well-structured summary with key facts, different perspectives, and sources.
    Always cite the URLs where you found information.
    """;

// --- Agent loop ---
Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var history = new List<ChatMessage>
    {
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\nResearching…\n");
    Console.ResetColor();

    var response = await chatClient.GetResponseAsync(history, tools);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();
    Console.WriteLine();
}

// =====================  Tool definitions  =====================

/// <summary>Searches the web via DuckDuckGo HTML and returns a list of result snippets.</summary>
sealed class WebSearch
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for a query and return the top result snippets with URLs.")]
    public async Task<string> SearchAsync(
        [Description("The search query")] string query,
        [Description("Max results to return")] int maxResults = 5)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🔍  Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var response = await Http.SendAsync(request);
            var html = await response.Content.ReadAsStringAsync();

            return ParseResults(html, maxResults);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string ParseResults(string html, int max)
    {
        var sb = new StringBuilder();
        int count = 0;

        // Match result links and snippets from DuckDuckGo HTML
        var linkPattern = new Regex(
            @"<a[^>]+class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);
        var snippetPattern = new Regex(
            @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);

        var links = linkPattern.Matches(html);
        var snippets = snippetPattern.Matches(html);

        for (int i = 0; i < links.Count && count < max; i++, count++)
        {
            var rawUrl = links[i].Groups[1].Value;
            // DuckDuckGo wraps URLs in a redirect; extract the actual URL
            var uddgMatch = Regex.Match(rawUrl, @"[?&]uddg=([^&]+)");
            var actualUrl = uddgMatch.Success
                ? Uri.UnescapeDataString(uddgMatch.Groups[1].Value)
                : rawUrl;

            var title = StripHtml(links[i].Groups[2].Value);
            var snippet = i < snippets.Count
                ? StripHtml(snippets[i].Groups[1].Value)
                : "";

            sb.AppendLine($"[{count + 1}] {title}");
            sb.AppendLine($"    URL: {actualUrl}");
            if (!string.IsNullOrWhiteSpace(snippet))
                sb.AppendLine($"    {snippet}");
            sb.AppendLine();
        }

        return count == 0
            ? "No results found."
            : sb.ToString();
    }

    private static string StripHtml(string s) =>
        HttpUtility.HtmlDecode(Regex.Replace(s, "<.*?>", "")).Trim();
}

/// <summary>Simple in-memory notebook for the agent to store and retrieve findings.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save an important finding as a note for later reference.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝  Note saved ({_notes.Count} total)");
        Console.ResetColor();
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"Note {i + 1}: {_notes[i]}");
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

